import {visitorName,rememberName} from './visitor.js';
import {bird} from './art.js';
import {drawer,mountDrawer} from './drawer.js';
const keyArt=`<svg viewBox="0 0 100 45" aria-hidden="true"><circle cx="22" cy="22" r="15" fill="none" stroke="currentColor" stroke-width="5"/><path d="M37 22h52m-9 0v12m-13-12v9" fill="none" stroke="currentColor" stroke-width="5" stroke-linecap="round"/></svg>`;
function door(){return `<div class="door-frame" aria-hidden="true"><div class="door-light"></div><div class="door-leaf"><div class="door-window"><span></span><span></span><span></span></div><div class="door-name">BELLAMY<small>OFICINA & IDEIAS POR TERMINAR</small></div><div class="door-panels"><i></i><i></i></div><div class="door-lock"><span></span></div><div class="door-sign">já volto.<small>eu acho.</small></div></div><div class="door-step"></div></div>`}
export function entrance(){return `<section class="entrance" aria-labelledby="arrival-title"><header class="arrival-header"><span>LIOR BELLAMY</span><span>ANTES DA PRIMEIRA PÁGINA</span></header><div id="arrival-stage"><div class="arrival-layout"><div class="arrival-copy"><span class="eyebrow">VOCÊ CHEGOU UM POUCO CEDO.</span><h1 id="arrival-title">A oficina<br>está <em>fechada.</em></h1><p>Há luz lá dentro.<br>Uma encomenda do lado de fora.<br>E um bilhete que parece ter sido escrito com pressa.</p><form id="door-name-form"><div class="arrival-note"><span class="tape"></span><p>“Se chegar antes de mim, termina a caixinha?<br>Um toque de sino. Eu escuto daqui.”</p><span>L.</span><label for="door-name">E quando eu ouvir o sino, como te chamo?</label><input id="door-name" name="apelido" maxlength="32" required autocomplete="nickname" placeholder="Seu nome ou apelido"></div><button type="submit" id="arrival-start" class="arrival-primary">Examinar a encomenda <span>↗</span></button></form><p class="arrival-small">Sem pressa. As pistas estão na bancada.</p></div><div class="arrival-door">${door()}<span class="door-caption">Algumas portas abrem com uma pequena ideia.</span></div></div></div><footer class="arrival-footer"><span>MADEIRA, LATÃO & UM POUCO DE PACIÊNCIA.</span><span>feito por ezy.xyz</span></footer></section>`}
export function mountEntrance(onEnter){const root=document.querySelector('.entrance'),stage=root.querySelector('#arrival-stage');let disposeGame=()=>{},timeout,opening=false;const controller=new AbortController();function openDoor(helped=false){if(opening)return;opening=true;disposeGame();root.classList.add('arrival-opening');stage.innerHTML=`<div class="arrival-finale" tabindex="-1"><span class="eyebrow">${helped?'ÀS VEZES, UMA MÃO AJUDA.':'UM TOQUE. ERA SÓ ISSO.'}</span><h1 id="arrival-title">${helped?'Pronto. Fizemos juntos.':'Alguém ouviu você.'}</h1><p>${helped?'Lior encaixou as últimas peças ao seu lado. O sino tocou.':'O sino tocou uma vez. Do outro lado, uma chave girou.'}</p><div class="opening-scene">${door()}<div class="arrival-flying-bird">${bird()}<span class="flying-key">${keyArt}</span></div><span class="settled-key">${keyArt}</span></div><p class="arrival-welcome">“Pode entrar. Só não mexe em…<br><em>deixa pra lá.</em>”</p><button id="arrival-enter" class="arrival-primary">Entrar na oficina <span>↗</span></button></div>`;stage.querySelector('.arrival-welcome').textContent='“Ouvi daqui, '+visitorName()+'. Pode entrar.”';stage.querySelector('.arrival-finale').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;root.classList.add(reduced?'arrival-reduced':'arrival-unlocking');timeout=setTimeout(()=>{root.classList.add('arrival-ready')},reduced?0:2300)}const input=root.querySelector('#door-name');
input.value=visitorName();
input.addEventListener('input',()=>input.setCustomValidity(''));
root.querySelector('#door-name-form').addEventListener('submit',e=>{
 e.preventDefault();
 if(!input.value.trim()){input.setCustomValidity('Escreva seu nome ou apelido.');input.reportValidity();return}
 rememberName(input.value);
 stage.innerHTML=`<div class="arrival-work"><div class="arrival-work-top"><span>VOCÊ ESTÁ NA PORTA DA OFICINA</span><span>UM PEDIDO. ALGUMAS TENTATIVAS.</span></div>${drawer()}</div>`;const back=stage.querySelector('.back-small');back.remove();const h=stage.querySelector('.drawer-heading h1');h.id='arrival-title';stage.querySelector('.drawer-heading>p').innerHTML='O bilhete pede um toque.<br>O resto fica por sua conta.';disposeGame=mountDrawer({onComplete:()=>openDoor(false)});window.scrollTo({top:0,behavior:'instant'});h.tabIndex=-1;h.focus({preventScroll:true})},{signal:controller.signal});
root.addEventListener('click',e=>{if(e.target.closest('#arrival-enter'))onEnter()},{signal:controller.signal});return ()=>{clearTimeout(timeout);disposeGame();controller.abort()}}
